"""Validating what the model returned (spec §4.2).

Spec §4.2 states three rules, and this module is all three:

* **Unsourced claims are discarded.** Not downgraded - removed. A claim with
  no citation is indistinguishable from a fabrication.
* **Each material claim requires >=2 independent sources**, or it is marked
  low-confidence and queued for human review.
* **CVE IDs are never generated by the model.** The pipeline supplies the
  id; this re-checks that nothing in the extraction contradicts it.

"Independent" means different publishers, not different URLs: a vendor
advisory and its own mirror are one source. Independence is judged by
registrable domain, which is an approximation - good enough to stop the
common case of one page cited twice, and documented as such.
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field
from urllib.parse import urlparse

import structlog

from aegis.core.enums import Confidence
from aegis.intel.extraction.schemas import AdvisoryExtraction, ExtractedSource

log = structlog.get_logger(__name__)

__all__ = [
    "ValidatedExtraction",
    "independent_publishers",
    "registrable_domain",
    "validate_extraction",
]

#: Fields that carry a material claim and therefore need citations.
MATERIAL_FIELDS = (
    "exploit_status",
    "vendor_confirmed",
    "patch_available",
    "config_dependent",
    "affected_versions",
)

#: Claims that change what a client is told to do out of hours.  These are
#: held to the two-source rule strictly; a single source leaves them
#: low-confidence and queued, never auto-issued.
HIGH_STAKES_FIELDS = frozenset({"exploit_status", "vendor_confirmed"})

#: Second-level domains that are really public suffixes, so the registrable
#: domain is the last three labels. Not exhaustive - a full public suffix
#: list belongs in a deployment that needs one.
_TWO_PART_SUFFIXES = frozenset(
    {"co.uk", "org.uk", "ac.uk", "gov.uk", "com.au", "co.jp", "co.nz", "com.br"}
)

_SCHEME = re.compile(r"^https?://", re.I)


@dataclass(slots=True)
class ValidatedExtraction:
    """What survived validation, and what a reviewer needs to know."""

    extraction: AdvisoryExtraction
    #: Fields kept, with the number of independent publishers backing each.
    accepted: dict[str, int] = field(default_factory=dict)
    #: Fields removed for want of any citation.
    discarded: list[str] = field(default_factory=list)
    #: Fields kept but backed by a single publisher.
    single_sourced: list[str] = field(default_factory=list)
    #: Spec §4.2: low-confidence extractions are queued for human review.
    needs_review: bool = False
    review_reasons: list[str] = field(default_factory=list)

    @property
    def confidence(self) -> Confidence:
        return self.extraction.confidence

    @property
    def has_claims(self) -> bool:
        return bool(self.accepted)


def registrable_domain(url: str) -> str | None:
    """The publisher behind a URL, for the independence test.

    Returns ``None`` for anything that is not an absolute http(s) URL, which
    makes such a citation count for nothing.
    """
    if not url or not _SCHEME.match(url.strip()):
        return None

    host = (urlparse(url.strip()).hostname or "").lower().strip(".")
    if not host:
        return None

    labels = host.split(".")
    if len(labels) < 2:
        return host

    last_two = ".".join(labels[-2:])
    if last_two in _TWO_PART_SUFFIXES and len(labels) >= 3:
        return ".".join(labels[-3:])
    return last_two


def independent_publishers(sources: list[ExtractedSource]) -> set[str]:
    """Distinct publishers among these citations.

    A citation with no quote does not count: spec §4.2 requires a supporting
    quote, and a bare URL is an assertion that something somewhere says so.
    """
    publishers: set[str] = set()
    for source in sources:
        if not source.quote or not source.quote.strip():
            continue
        domain = registrable_domain(source.url)
        if domain:
            publishers.add(domain)
    return publishers


def validate_extraction(
    extraction: AdvisoryExtraction,
    *,
    expected_cve_id: str,
    fetched_from: str | None = None,
) -> ValidatedExtraction:
    """Apply spec §4.2's rules to one extraction.

    Args:
        extraction: What the model returned.
        expected_cve_id: The CVE the page was fetched for.  Supplied by the
            pipeline, never by the model.
        fetched_from: The URL the text came from, counted as a publisher
            when the model cited it without a full URL.

    Returns:
        The extraction with unsourced claims removed, plus what a reviewer
        needs to know about what remains.
    """
    result = ValidatedExtraction(extraction=extraction)

    by_field = _sources_by_field(extraction, fetched_from)
    all_publishers = independent_publishers(extraction.sources)

    for name in MATERIAL_FIELDS:
        value = getattr(extraction, name)
        if value is None or (isinstance(value, list) and not value):
            continue

        # A citation naming the field backs it; otherwise the page's own
        # publishers back everything it asserts.
        publishers = by_field.get(name) or all_publishers

        if not publishers:
            # Spec §4.2: unsourced claims are discarded.
            _clear(extraction, name)
            result.discarded.append(name)
            log.info("extraction.claim_discarded", cve=expected_cve_id, field=name)
            continue

        result.accepted[name] = len(publishers)
        if len(publishers) < 2:
            result.single_sourced.append(name)

    if not result.accepted:
        result.needs_review = True
        result.review_reasons.append("no claim survived validation")

    # Spec §4.2: fewer than two independent sources means low confidence and
    # a human look.
    gated = [name for name in result.single_sourced if name in HIGH_STAKES_FIELDS]
    if gated:
        extraction.confidence = Confidence.LOW
        result.needs_review = True
        result.review_reasons.append(
            f"single-sourced high-stakes claim(s): {', '.join(sorted(gated))}"
        )
    elif result.single_sourced:
        if extraction.confidence is Confidence.HIGH:
            extraction.confidence = Confidence.MEDIUM
        result.review_reasons.append(
            f"single-sourced claim(s): {', '.join(sorted(result.single_sourced))}"
        )

    if extraction.confidence is Confidence.LOW and result.accepted:
        result.needs_review = True
        if "low confidence" not in " ".join(result.review_reasons):
            result.review_reasons.append("low confidence extraction")

    if extraction.reviewer_note:
        result.needs_review = True
        result.review_reasons.append("the model flagged an ambiguity")

    log.info(
        "extraction.validated",
        cve=expected_cve_id,
        accepted=sorted(result.accepted),
        discarded=result.discarded,
        needs_review=result.needs_review,
    )
    return result


def _sources_by_field(
    extraction: AdvisoryExtraction, fetched_from: str | None
) -> dict[str, set[str]]:
    """Publishers backing each named field."""
    grouped: dict[str, set[str]] = {}
    fetched_domain = registrable_domain(fetched_from or "")

    for source in extraction.sources:
        if not source.field or not source.quote.strip():
            continue
        domain = registrable_domain(source.url) or fetched_domain
        if domain:
            grouped.setdefault(source.field, set()).add(domain)
    return grouped


def _clear(extraction: AdvisoryExtraction, name: str) -> None:
    """Remove a claim the model could not source."""
    if name == "affected_versions":
        extraction.affected_versions = []
    else:
        setattr(extraction, name, None)
